  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Atazanavir, a structurally related HIV protease inhibitor, has an absolute oral bioavailability of 68% (57–80%) in humans, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Atazanavir oral bioavailability is 69% under fasting conditions, matching the query's fasted condition and supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Amprenavir is orally bioavailable at >70% in humans, providing quantitative support for F ≥ 20% in this peptidomimetic protease-inhibitor class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Darunavir has an oral bioavailability of 37% when given alone; although described as low in some sources, 37% is above the 20% threshold and supports high.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "KNI-272, a peptidomimetic HIV protease inhibitor, has an absolute bioavailability of 33.99 ± 9.73% in fasting patients, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "CGP 38 560, a peptidomimetic with low similarity to the query, has <1% oral bioavailability in humans, providing a contradictory low-F data point but with limited transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C21"],
      "claim": "Lopinavir, the closest analogue, is reported to have low oral bioavailability due to CYP3A/P-gp, but no absolute F value is given, so it does not affirmatively establish F < 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Quantitative absolute bioavailability data from multiple structurally related HIV protease inhibitors (atazanavir 68%, amprenavir >70%, darunavir 37%, KNI-272 22–55%) support F ≥ 20% under fasting conditions. The closest analogue lopinavir is reported qualitatively as low but lacks a threshold-specific absolute F value, so it does not override the quantitative high-F evidence.",
